class DrawingTool {
  constructor(name, color) {
    this.name = name;
    this.color = color;
  }

  describe() {
    return `A ${this.color} ${this.name} tool.`;
  }
}

class Brush extends DrawingTool {
  constructor(name, color, size) {
    super(name, color);
    this.size = size;
  }

  draw() {
    const sizeDesc = this.size < 3 ? "thin" : (this.size < 10 ? "medium" : "thick");
    return `Drawing a ${sizeDesc} ${this.color} line.`;
  }
}

class Eraser extends DrawingTool {
  constructor(name, color, strength) {
    super(name, color);
    this.strength = strength;
  }

  erase() {
    const strengthDesc = this.strength < 0.5 ? "gentle" : (this.strength < 0.8 ? "moderate" : "strong");
    return `Erasing with ${strengthDesc} force.`;
  }
}

// Test cases (for local execution)
const fineBrush = new Brush("Fine Brush", "black", 1);
const broadBrush = new Brush("Broad Brush", "blue", 8);
const strongEraser = new Eraser("Strong Eraser", "white", 0.9);
const gentleEraser = new Eraser("Gentle Eraser", "transparent", 0.3);

console.log(fineBrush.describe());
console.log(fineBrush.draw());
console.log(broadBrush.draw());
console.log(strongEraser.describe());
console.log(strongEraser.erase());
console.log(gentleEraser.erase());

